-- DEV ONLY: assign all team members as direct reports to the dev user (tms_id=1) for testing
INSERT INTO DS.TBL_TMS_X_SUPERVISOR (TMS_ID, SUP_ID, TXS_STADAT, TXS_CREATED_BY, TXS_CREDAT)
SELECT TMS_ID, 1, '2015-01-01', 1, NOW()
FROM DS.TBL_TEAM_MEMBERS
WHERE TMS_ID != 1
  AND NOT EXISTS (
    SELECT 1 FROM DS.TBL_TMS_X_SUPERVISOR s
    WHERE s.TMS_ID = DS.TBL_TEAM_MEMBERS.TMS_ID AND s.SUP_ID = 1
  );